{
 "summary": "The first theorem proves that there is a connected, bipartite, 2-degenerate finite graph H with ex(n,H) ≥ c·n^{3/2+ε} for all large n, for some c, ε > 0. It also adds the condition that in every proper 2-colouring, each colour class contains a vertex of degree > 2. The second theorem proves the negation of Erdős's conjecture that every bipartite r-degenerate graph (r > 0) satisfies ex(n,H) = O(n^{2−1/r}). The definitions appear faithful; the only deviation is the extra degree conjunct, which makes the Lean statement stronger than the paper.",
 "glossary": [
  {"decl": "neighborsWithin", "line": 8, "plain": "N_G(v) ∩ s, the neighbours of v inside the finite set s", "standard_concept": "neighbourhood restricted to a vertex subset", "matches_standard": "yes", "note": ""},
  {"decl": "IsDegenerate", "line": 13, "plain": "Every nonempty finite vertex set s contains a vertex with at most r neighbours in s (the induced subgraph on s has minimum degree ≤ r).", "standard_concept": "r-degenerate graph", "matches_standard": "yes", "note": "Using induced subgraphs is equivalent to the paper's 'every nonempty subgraph' formulation, since deleting edges only lowers degrees."},
  {"decl": "IsTwoDegenerate", "line": 17, "plain": "IsDegenerate 2", "standard_concept": "2-degenerate", "matches_standard": "yes", "note": ""},
  {"decl": "DegeneracyConjectureStatement", "line": 20, "plain": "For all r > 0 and every finite bipartite r-degenerate graph H on Fin q: ex(n,H) = O(n^{2−1/r}) as n → ∞.", "standard_concept": "Erdős degeneracy conjecture (3)", "matches_standard": "yes", "note": "The hypothesis r > 0 excludes 1/0; the r = 0 case is trivial anyway."}
 ],
 "lean_claims": [
  {"theorem": "twoDegenerateExtremalCounterexample", "line": 28, "plain": "There exist q and a graph H on Fin q, together with reals c > 0 and ε > 0, such that: H is connected, bipartite and 2-degenerate; for every proper 2-colouring of H, each colour class contains a vertex of degree > 2; and for all sufficiently large n, c·n^{3/2+ε} ≤ ex(n,H) (Mathlib extremalNumber)."},
  {"theorem": "not_erdos_146", "line": 43, "plain": "There exist r > 0 and a finite bipartite r-degenerate graph H such that ex(n,H) is not O(n^{2−1/r})."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.2", "plain": "There exist a fixed connected bipartite 2-degenerate graph H and constants c, ε > 0 such that ex(n,H) ≥ c·n^{3/2+ε} for all sufficiently large n."},
  {"ref": "Abstract/§1.2 (disproof of Erdős's conjecture (3))", "plain": "Not every bipartite r-degenerate graph satisfies ex(n,H) = O(n^{2−1/r}); this fails already for r = 2."},
  {"ref": "Theorem 1.1", "plain": "Failure of compactness (covered elsewhere, sibling file)."}
 ],
